using System;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;
using Object=UnityEngine.Object;

public static class GridShiftV21Setup {
 const string Folder="Assets/Generated/Character21";static readonly Dictionary<Texture,Texture2D> readable=new Dictionary<Texture,Texture2D>();
 public static void Batch(){try{Prepare();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void Prepare(){Directory.CreateDirectory(Folder);Directory.CreateDirectory("Docs/Validacao21");var source=Resources.Load<GridShiftCitizenCatalog>("GridShiftCitizenCatalog");var output=AssetDatabase.LoadAssetAtPath<GridShiftAvatarCatalog>("Assets/Resources/GridShiftAvatarCatalog.asset");if(output==null){output=ScriptableObject.CreateInstance<GridShiftAvatarCatalog>();AssetDatabase.CreateAsset(output,"Assets/Resources/GridShiftAvatarCatalog.asset");}var models=new List<GameObject>();var report=new System.Text.StringBuilder();
  for(int index=0;index<source.models.Length;index++){var original=source.models[index];var changed=new List<string>();foreach(var renderer in original.GetComponentsInChildren<Renderer>()){var originalMesh=renderer is SkinnedMeshRenderer sm?sm.sharedMesh:renderer.GetComponent<MeshFilter>()?.sharedMesh;if(originalMesh==null)continue;var path=AssetDatabase.GetAssetPath(originalMesh);var importer=AssetImporter.GetAtPath(path) as ModelImporter;if(importer!=null&&!importer.isReadable){importer.isReadable=true;importer.SaveAndReimport();changed.Add(path);}}
   var clone=Object.Instantiate(original);clone.name="Visual "+(index+1).ToString("00");int skins=0,clothes=0,serial=0;
   try{int skinCell=SkinCell(clone);foreach(var renderer in clone.GetComponentsInChildren<Renderer>()){var skinned=renderer as SkinnedMeshRenderer;var filter=renderer.GetComponent<MeshFilter>();var mesh=skinned!=null?skinned.sharedMesh:filter!=null?filter.sharedMesh:null;if(mesh==null||mesh.vertexCount==0)continue;var vertices=mesh.vertices;var uv=mesh.uv;var weights=mesh.boneWeights;var groups=new[]{new List<int>(),new List<int>(),new List<int>()};var originalMaterial=renderer.sharedMaterial;var image=Read(originalMaterial!=null?originalMaterial.GetTexture("_BaseMap"):null);
     for(int sub=0;sub<mesh.subMeshCount;sub++){var triangles=mesh.GetTriangles(sub);for(int i=0;i<triangles.Length;i+=3){int vertex=triangles[i];string bone="";if(weights.Length>vertex&&skinned!=null&&skinned.bones.Length>weights[vertex].boneIndex0)bone=skinned.bones[weights[vertex].boneIndex0].name.ToLowerInvariant();bool head=skinned==null||bone.Contains("head")||bone.Contains("neck"),limb=bone.Contains("hand")||bone.Contains("arm")||bone.Contains("leg")||bone.Contains("thumb")||bone.Contains("index")||bone.Contains("middle")||bone.Contains("ring")||bone.Contains("pinky");var color=image!=null&&uv.Length>vertex?image.GetPixelBilinear((uv[triangles[i]].x+uv[triangles[i+1]].x+uv[triangles[i+2]].x)/3,(uv[triangles[i]].y+uv[triangles[i+1]].y+uv[triangles[i+2]].y)/3):Color.white;var triangleUV=(uv[triangles[i]]+uv[triangles[i+1]]+uv[triangles[i+2]])/3;bool warm=triangleUV.y<1f/6f+.0001f&&Mathf.Clamp(Mathf.FloorToInt(triangleUV.x*36),0,35)==skinCell;bool detail=renderer.name.ToLowerInvariant().Contains("eye")||renderer.name.ToLowerInvariant().Contains("mouth");bool hand=bone.Contains("hand")||bone.Contains("thumb")||bone.Contains("index")||bone.Contains("middle")||bone.Contains("ring")||bone.Contains("pinky");int group=!detail&&warm?1:!detail&&!head&&!hand?2:0;for(int j=0;j<3;j++)groups[group].Add(triangles[i+j]);}}
     var baked=Object.Instantiate(mesh);baked.name=clone.name+" mesh "+serial;baked.subMeshCount=3;for(int g=0;g<3;g++)baked.SetTriangles(groups[g],g);var meshPath=Folder+"/model-"+index+"-"+serial+".asset";ReplaceAsset(baked,meshPath);if(skinned!=null)skinned.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);else filter.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);var skin=Object.Instantiate(originalMaterial);skin.name="GS Skin "+index+"-"+serial;var cloth=Object.Instantiate(originalMaterial);cloth.name="GS Outfit "+index+"-"+serial;var skinPath=Folder+"/skin-"+index+"-"+serial+".mat";var clothPath=Folder+"/outfit-"+index+"-"+serial+".mat";ReplaceAsset(skin,skinPath);ReplaceAsset(cloth,clothPath);renderer.sharedMaterials=new[]{originalMaterial,AssetDatabase.LoadAssetAtPath<Material>(skinPath),AssetDatabase.LoadAssetAtPath<Material>(clothPath)};skins+=groups[1].Count/3;clothes+=groups[2].Count/3;serial++;}
    var prefab=PrefabUtility.SaveAsPrefabAsset(clone,Folder+"/Visual-"+(index+1).ToString("00")+".prefab");models.Add(prefab);report.AppendLine("MODEL "+index+" skinCell="+skinCell+" skinTriangles="+skins+" outfitTriangles="+clothes);if(skins==0||clothes==0)throw new Exception("Model has no recolorable skin or clothing: "+index);
   }finally{Object.DestroyImmediate(clone);foreach(var path in changed){var importer=(ModelImporter)AssetImporter.GetAtPath(path);importer.isReadable=false;importer.SaveAndReimport();}}
  }
  var atlas=Read(source.models[0].GetComponentInChildren<SkinnedMeshRenderer>().sharedMaterial.GetTexture("_BaseMap"));var tone=new Texture2D(1024,1024,TextureFormat.RGBA32,false);var pixels=new Color32[1024*1024];for(int y=0;y<1024;y++)for(int x=0;x<1024;x++){var c=atlas.GetPixelBilinear((x+.5f)/1024,(y+.5f)/1024);byte v=(byte)(Mathf.Clamp01((c.r*.2126f+c.g*.7152f+c.b*.0722f)*2)*255);pixels[y*1024+x]=new Color32(v,v,v,255);}tone.SetPixels32(pixels);tone.Apply();string tonePath=Folder+"/AvatarTone.png";File.WriteAllBytes(tonePath,tone.EncodeToPNG());Object.DestroyImmediate(tone);AssetDatabase.ImportAsset(tonePath);var ti=(TextureImporter)AssetImporter.GetAtPath(tonePath);ti.textureCompression=TextureImporterCompression.Uncompressed;ti.mipmapEnabled=false;ti.sRGBTexture=true;ti.SaveAndReimport();output.toneTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(tonePath);output.models=models.ToArray();EditorUtility.SetDirty(output);AssetDatabase.SaveAssets();foreach(var texture in readable.Values)Object.DestroyImmediate(texture);readable.Clear();report.AppendLine("RESULT SUCCESS");File.WriteAllText("Docs/Validacao21/catalogo.txt",report.ToString());
 }
 static int SkinCell(GameObject model){var totals=new float[36];foreach(var r in model.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=r.sharedMesh;var uv=mesh.uv;var weights=mesh.boneWeights;var vertices=mesh.vertices;var triangles=mesh.triangles;for(int i=0;i<triangles.Length;i+=3){int a=triangles[i],b=triangles[i+1],c=triangles[i+2];if(weights.Length<=a||uv.Length<=a||weights[a].boneIndex0>=r.bones.Length)continue;string bone=r.bones[weights[a].boneIndex0].name.ToLowerInvariant();bool hand=bone.Contains("hand"),head=bone.Contains("head")||bone.Contains("neck");if(!head&&!hand)continue;var point=(uv[a]+uv[b]+uv[c])/3;if(point.y>=1f/6f+.0001f||point.x<.5f)continue;int cell=Mathf.Clamp(Mathf.FloorToInt(point.x*36),18,35);totals[cell]+=Vector3.Cross(vertices[b]-vertices[a],vertices[c]-vertices[a]).magnitude*(hand?5:1);}}int chosen=18;for(int i=19;i<36;i++)if(totals[i]>totals[chosen])chosen=i;return chosen;}
 static void ReplaceAsset(Object value,string path){var prior=AssetDatabase.LoadMainAssetAtPath(path);if(prior==null)AssetDatabase.CreateAsset(value,path);else{EditorUtility.CopySerialized(value,prior);EditorUtility.SetDirty(prior);Object.DestroyImmediate(value);}}
 static Texture2D Read(Texture texture){if(texture==null)return null;if(readable.TryGetValue(texture,out var result))return result;var target=RenderTexture.GetTemporary(texture.width,texture.height,0,RenderTextureFormat.ARGB32);var old=RenderTexture.active;Graphics.Blit(texture,target);RenderTexture.active=target;result=new Texture2D(texture.width,texture.height,TextureFormat.RGBA32,false);result.ReadPixels(new Rect(0,0,texture.width,texture.height),0,0);result.Apply();RenderTexture.active=old;RenderTexture.ReleaseTemporary(target);readable[texture]=result;return result;}
}
